<?php
declare(strict_types=1);session_start();require_once "db.php";if(!isset($_SESSION["admin"])){header("Location: admin_login.php");exit();}function e($v){return htmlspecialchars((string)$v,ENT_QUOTES,"UTF-8");}$msg="";$err="";
if($_SERVER["REQUEST_METHOD"]==="POST"){$code=strtoupper(trim((string)$_POST["guard_code"]));$name=trim((string)$_POST["full_name"]);$user=trim((string)$_POST["username"]);$pass=(string)$_POST["password"];$type=(string)$_POST["guard_type"];if(strlen($pass)<8)$err="Password minimum 8 aksara.";else{$hash=password_hash($pass,PASSWORD_DEFAULT);$s=$conn->prepare("INSERT INTO security_guards(guard_code,full_name,username,password,guard_type) VALUES(?,?,?,?,?)");$s->bind_param("sssss",$code,$name,$user,$hash,$type);if($s->execute())$msg="Akaun pengawal berjaya dicipta.";else$err="Guard Code atau username sudah digunakan.";$s->close();}}
$guards=[];$r=$conn->query("SELECT * FROM security_guards ORDER BY full_name");while($r&&$x=$r->fetch_assoc())$guards[]=$x;$conn->close();
?><!doctype html><html lang="ms"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Security Guards</title><link rel="stylesheet" href="css/security_patrol.css?v=1"></head><body><div class="wrap"><header class="header"><div><h1>Security Guard Management</h1><p>2 pengawal tetap dan buffer jika perlu</p></div><a class="btn" href="admin_dashboard.php">Admin Dashboard</a></header><?php if($msg):?><div class="alert ok"><?=e($msg)?></div><?php endif;if($err):?><div class="alert err"><?=e($err)?></div><?php endif;?><section class="card"><h2>Tambah Akaun Pengawal</h2><form method="post" class="grid"><div class="group"><label>Guard Code</label><input name="guard_code" placeholder="GRD-001" required></div><div class="group"><label>Nama</label><input name="full_name" required></div><div class="group"><label>Username</label><input name="username" required></div><div class="group"><label>Password</label><input type="password" name="password" minlength="8" required></div><div class="group"><label>Jenis</label><select name="guard_type"><option>Permanent</option><option>Buffer</option><option>Relief</option></select></div><button class="btn full">Cipta Akaun</button></form></section><section class="card"><h2>Senarai Pengawal</h2><table><tr><th>Code</th><th>Nama</th><th>Username</th><th>Jenis</th><th>Status</th></tr><?php foreach($guards as $g):?><tr><td><?=e($g["guard_code"])?></td><td><?=e($g["full_name"])?></td><td><?=e($g["username"])?></td><td><?=e($g["guard_type"])?></td><td><?=e($g["account_status"])?></td></tr><?php endforeach;?></table></section></div></body></html>
